    if (ratio >= 0.2) return { status: 'High', color: 'text-green-400' };
    if (ratio >= 0.1) return { status: 'Medium', color: 'text-yellow-400' };
    if (ratio >= 0.05) return { status: 'Low', color: 'text-orange-400' };
    return { status: 'Very Low', color: 'text-red-400' };
  };

